/// <summary>
        /// Elimina logicamente el elemento Silos indicado
        /// </summary>
        /// <param name="elemento"></param>
        /// <param name="usuario"></param>
        public void EliminarElemento(Silos elemento)
        {
            try
            {
                _persistencia.Usuario = elemento.Au_Usuario;
                _persistencia.BeginTrans();
                Consulta consulta = new Consulta("PR_CT_SILOS")
                {
                    CamposValor = new Dictionary<string, object>
                    {
                         {"AU_USUARIO", elemento.Au_Usuario},
                         {"AU_FECHA_MOD", "CURRENT DATE"},
                         {"AU_HORA_MOD", "CURRENT TIME"},
                         {"AU_TERMINAL", elemento.Au_Terminal},
                         {"AU_BORRADO", 1},
                    },
                    CondicionesWhere = new List<CondicionWhere> 
                    {
                        new CondicionWhere("PK_SILO", Operadores.IGUAL, elemento.Id.Pk_Silo, false)
                    }
                };

                _persistencia.Modificar(consulta, _persistencia.Trans);
                _persistencia.CommitTrans();
            }
            catch (Exception ex)
            {
                _persistencia.RollbackTrans();
                throw new Exception(ex.Message);
            }
        }

/// <summary>
        /// Obtiene la consulta generica para la tabla PR_CT_SILOS 
        /// </summary>
        private static Consulta GetConsulta()
        {
            Consulta consulta = new Consulta("PR_CT_SILOS AS " + _alias)
            {
                Campos = string.Format(@"
                    {0}.PK_SILO,
                    {0}.FK_PLANTA,
                    {0}.FK_MATERIA_PRIMA,
                    {0}.CLAVE_CORTA,
                    {0}.NOMBRE,
                    {0}.AU_USUARIO,
                    {0}.AU_FECHA_MOD,
                    {0}.AU_HORA_MOD,
                    {0}.AU_TERMINAL,
                    {0}.AU_BORRADO,
                    PLANTA.NOMBRE_PLANTA,
                    MATPRI.DESCRIPCION", _alias),
                CondicionesJoin = new List<CondicionJoin> 
                {
                    new CondicionJoin(TipoJoin.INNER, "BB_CT_PLANTAS AS PLANTA")
                    {CamposCondicion = new List<CamposCondicion>{new CamposCondicion(_alias + ".FK_PLANTA", Operadores.IGUAL, "PLANTA.PK_PLANTA", true) }},
                    new CondicionJoin(TipoJoin.INNER, "BB_CT_MATERIAS_PRIMAS AS MATPRI")
                    {CamposCondicion = new List<CamposCondicion>{new CamposCondicion(_alias + ".FK_MATERIA_PRIMA", Operadores.IGUAL, "MATPRI.PK_MATERIA_PRIMA", true) }},
                }
            };

            return consulta;
        }

