/// <summary>
        /// Consulta el rol de monitoreo.
        /// </summary>
        /// <param name="criterios">Los criterios de la consulat.</param>
        /// <param name="usuario">El usuario que tiene sesión iniciada.</param>
        /// <returns>DataRow.</returns>
        public DataRow ConsultarRolPersonalMonitoreo(List<CriterioValor> criterios, string usuario)
        {
            _persistencia.Usuario = usuario;
            Consulta consulta = ConsultaPersonalMonitoreo();

            if (criterios != null && criterios.Count > 0)
                consulta.CondicionesWhere = UtileriasBB.ObtenerCriteriosBusqueda(criterios, false, null);

            if (consulta.CondicionesWhere is null)
                consulta.CondicionesWhere = new List<CondicionWhere>();

            // Se consultan los registros que no han sido eliminados ()
            consulta.CondicionesWhere.Add(new CondicionWhere("tcr.AU_BORRADO", Operadores.IGUAL, 0, true));

            DataSet ds = _persistencia.Consultar(consulta);

            if (ds.Tables[0].Rows.Count > 0)
                return ds.Tables[0].Rows[0];

            return null;
        }

