        #region Pedidos_Embarques

        public List<ViajesPedidos> ConsultaElementosPedidosEmbarque(string usuario, string jurisdiccion, List<CriterioValor> criteriosAplicados = null)
        {
            _persistencia.Usuario = usuario;
            List<ViajesPedidos> _lstViajesPedidos = new List<ViajesPedidos>();

            Consulta consulta = new Consulta(string.Format("TABLE(TR_FN_CONSULTA_PEDIDOS_EMBARQUE('{0}')) AS FUNCION", jurisdiccion))
            {
                Campos = string.Format(@"
                    FUNCION.*,
                    SFAC.NOMBRE_SUCURSAL"),
                CondicionesJoin = new List<CondicionJoin>
                {
                    new CondicionJoin(TipoJoin.LEFT,"BB_CT_SUCURSALES SFAC")
                        { CamposCondicion = new List<CamposCondicion> { new CamposCondicion("FUNCION.FK_SUCURSAL", Operadores.IGUAL, "SFAC.PK_SUCURSAL", true) }},
                }
            };

            if (criteriosAplicados != null && criteriosAplicados.Count > 0)
            {
                consulta.CondicionesWhere = UtileriasBB.ObtenerCriteriosBusqueda(criteriosAplicados, false, _alias);
            }

            DataSet ds = _persistencia.Consultar(consulta);

            if (ds.Tables[0].Rows.Count > 0)
                _lstViajesPedidos.AddRange(from DataRow row in ds.Tables[0].Rows select toobjectPedidoEmbarque(row));

            return _lstViajesPedidos;
        }

