        private static Evento toObject(DataRow row)
        {
            Evento obj = new Evento
            {
                Id = new IDEvento 
                {
                    Pk_Evento = Convert.ToInt32(row["PK_EVENTO"]),
                },
                Clave_Corta = row["CLAVE_CORTA"] != DBNull.Value ? row["CLAVE_CORTA"].ToString() : String.Empty,
                Tipo_Evento = row["TIPO_EVENTO"] != DBNull.Value ? row["TIPO_EVENTO"].ToString() : String.Empty,
                Motivo_Evento = row["MOTIVO_EVENTO"] != DBNull.Value ? row["MOTIVO_EVENTO"].ToString() : String.Empty,
                Au_Fecha_Mod = FormatoFecha.ObtenerFecha(row["AU_FECHA_MOD"].ToString()),
                Au_Hora_Mod = FormatoFecha.ObtenerFecha(row["AU_HORA_MOD"].ToString()).TimeOfDay,
                Au_Usuario = row["AU_USUARIO"] != DBNull.Value ? row["AU_USUARIO"].ToString() : String.Empty,
                Au_Terminal = row["AU_TERMINAL"] != DBNull.Value ? row["AU_TERMINAL"].ToString() : String.Empty,
                Au_Borrado = row["AU_BORRADO"] != DBNull.Value ? Convert.ToInt32(row["AU_BORRADO"]) : 0,
                Solicitar_Observaciones = row["SOLICITAR_OBSERVACIONES"] != DBNull.Value ? Convert.ToInt32(row["SOLICITAR_OBSERVACIONES"]) : 0,
                Dinamico = row["DINAMICO"] != DBNull.Value ? Convert.ToInt32(row["DINAMICO"]) : 0,
                Estatus = row["ESTATUS"] != DBNull.Value ? row["ESTATUS"].ToString() : String.Empty,
            };
            return obj;
        }

