/// <summary>
        /// Modifica el Conductor del Rol elegido.
        /// </summary>
        /// <param name="elemento"></param>
        /// <param name="ModifyRolTurno"></param>
        public void ModificaConductorRol(RolUrbano elemento)
        {
            try
            {
                _persistencia.Usuario = elemento.Au_Usuario;
                _persistencia.BeginTrans();

                Consulta consulta = new Consulta("TR_CT_ROLES_URBANOS")
                {
                    CamposValor = new Dictionary<string, object>
                    {
                        { "FK_CONDUCTOR", elemento.Conductor.Id.Pk_Conductor },
                        { "AU_FECHA_MOD", "CURRENT DATE" },
                        { "AU_HORA_MOD", "CURRENT TIME" },
                        { "AU_USUARIO", elemento.Au_Usuario },
                        { "AU_TERMINAL", elemento.Au_Terminal },
                        { "AU_BORRADO", 0 }
                    }
                };

                consulta.CondicionesWhere = new List<CondicionWhere>
                {
                    new CondicionWhere("PK_ROL_URBANO", Operadores.IGUAL, elemento.Id.pkRolUrbano, true)
                };

                _persistencia.Modificar(consulta, _persistencia.Trans);
                _persistencia.CommitTrans();
            }
            catch (Exception ex)
            {
                _persistencia.RollbackTrans();
                throw new Exception(ex.Message);
            }
        }

