                #endregion

                #region Conceptos_requeridos

                List<ConceptosGastos> lstConceptosRequeridos = new List<ConceptosGastos>();

                NVariableSistema NVarSis = new NVariableSistema();
                VariableSistema varSis = NVarSis.ConsultarElemento("CONVALGAS", "INDICA LOS CONCEPTOS VALIDOS A MOSTRAR EN ASIGNACION GASTOS", 0, "1,2", true, (Session["SessionR1"] as Session).Usuario.Id.Login);

                if (varSis.Valor_String != null && varSis.Valor_String != string.Empty)
                {
                    var filtro = (from item in varSis.Valor_String.Split(',')
                                  select item).ToList();

                    filtro.ForEach(item => {
                        lstConceptosRequeridos.Add(new ConceptosGastos
                        {
                            Id = new IDTRConcepto { Pk_Concepto = Convert.ToInt32(item) },
                            Descripcion = (from itemConcepto in lstConceptos
                                           where itemConcepto.Id.Pk_Concepto == Convert.ToInt32(item)
                                           select itemConcepto.Descripcion).FirstOrDefault(),
                        });
                    });
                }

                Session["listaConceptosRequeridos"] = lstConceptosRequeridos;
                #endregion

                //Creacion columnas datatable
                DataTable dtt = new DataTable();
                //Estaticas
