                dtt.Columns.Add(new DataColumn { ColumnName = "TipoLiquidacion", DataType = System.Type.GetType("System.String") });
                dtt.Columns.Add(new DataColumn { ColumnName = "Estatus", DataType = System.Type.GetType("System.String") });
                dtt.Columns.Add(new DataColumn { ColumnName = "Viaje.Conductor.Nombre_Completo", DataType = System.Type.GetType("System.String") });
                dtt.Columns.Add(new DataColumn { ColumnName = "Viaje.Fecha_Inicia", DataType = System.Type.GetType("System.DateTime") });
                dtt.Columns.Add(new DataColumn { ColumnName = "Viaje.Fecha_Termina", DataType = System.Type.GetType("System.DateTime") });

protected void cbPopPFisicas_Callback(object source, CallbackEventArgs e)
        {
            NPersonaFisica _objNegocio = new NPersonaFisica();
            string resultado = "0";
            string _parametro = hfGeneral["opcion"].ToString();

            try
            {
                if(_parametro == "1" || _parametro == "2") //Nuevo y Modificación.
                {
                    PersonaFisica _objEntidad = new PersonaFisica()
                    {
                        Nombre_Completo = txtNombre.Text,
                        Rfc = txtRFC.Text,
                        Calle = txtCalle.Text,
                        Numero = txtNumero.Text,
                        Colonia = txtColonia.Text,
                        Codigo_postal = txtCodigoPostal.Text,
                        Telefono = txtTelefono.Text,
                        Sucursal = cbSucursal.Value != null ? new Sucursal { Id = new IDSucursal {  Pk_sucursal = int.Parse(cbSucursal.Value.ToString()) } } : null,
                        Departamento = cbDepartamento.Value != null ? new Departamento { Id = new IDDepartamento { Pk_Departamento = int.Parse(cbDepartamento.Value?.ToString())} } : null,
                        Au_Terminal = Request.UserHostName,
                        Au_Usuario = (ViewState["RowUsuario"] as Usuario).Id.Login
                    };

                    if (cbCiudad.Value != null)
                        _objEntidad.Ciudad = new Ciudad { Id = new IDCiudad { Pk_Ciudad = int.Parse(cbCiudad.Value.ToString()) } };

                    if (_parametro == "1")
                    {
                        var pkPersonaFisica = _objNegocio.AgregarElemento(_objEntidad);
                    }

                    else
                    {
                        string pkPF = dgvPFisicas.GetRowValues(dgvPFisicas.FocusedRowIndex, "PK_PERSONA_FISICA").ToString();
                        _objEntidad.Id = new IDPersonaFisica { Pk_Persona_Fisica = int.Parse(pkPF) };//txtPkPersonaFisica.Value.ToString()
                        _objNegocio.ModificarElemento(_objEntidad);
                    }
                }

                else if (_parametro == "3") //Eliminación.
                {
                    string pkPersonaFisica = dgvPFisicas.GetRowValues(dgvPFisicas.FocusedRowIndex, "PK_PERSONA_FISICA").ToString();
                    PersonaFisica elemento = new PersonaFisica()
                    {
                        Id = new IDPersonaFisica { Pk_Persona_Fisica = int.Parse(pkPersonaFisica) },
                        Au_Terminal = Request.UserHostName,
                        Au_Usuario = (ViewState["RowUsuario"] as Usuario).Id.Login,
                    };

                    _objNegocio.EliminarElemento(elemento);
                    resultado = "1";
                }

                e.Result = resultado;
            }
            catch(Exception ex)
            {
                resultado = "2";
                CatchError.saveLog(this, (ViewState["RowUsuario"] as Usuario).Id.Login, ex);
                throw new Exception(ex.Message);
            }
        }

