/// <summary>
        /// Inserta el nuevo concepto de nómina.
        /// </summary>
        /// <param name="indicador">El concepto de nómina.</param>
        private void InsertarConceptoNomina(ASPxDataInsertValues aspxIndicador)
        {
            var negocio = new NConceptoNomina();
            var concepto = new ConceptoNomina
            {
                ID = new IDConceptoNomina(),
                Personal_Registra = (Session["SessionR1"] as Session).Usuario.Id.Personal,
                Descripcion = (string)aspxIndicador.NewValues["Descripcion"],
                Tipo_Concepto = (string)aspxIndicador.NewValues["Tipo_Concepto"],
                Estatus = "0", // Es el valor entero de la Enumeración EstatusConceptoNomina
                Clave = (string)aspxIndicador.NewValues["Clave"],
                Au_Usuario = (Session["SessionR1"] as Session).Usuario.Id.Login,
                Au_Terminal = Request.UserHostName,
                Au_Borrado = 0
            };

            // Valida que la Clave sólo contenga letras y números.
            var res = Regex.IsMatch(concepto.Clave, @"^[A-Z0-9]+$");

            if (!res)
                throw new Exception("La CLAVE sólo puede contener letras mayúsculas y números");

            negocio.AgregarElemento(concepto);
        }

