/// <summary>
        /// Monitoristas the tiene turno abierto.
        /// </summary>
        /// <returns>System.String.</returns>
        private string MonitoristaTieneTurnoAbierto(RolMonitoreoTurno rolMonitoreo)
        {
            var objNRolMonitoreoTurno = new NRolMonitoreoTurno();
            var criterios = new List<CriterioValor>();
            var usuario = (Session["SessionR1"] as Session).Usuario;
            var objNMonitoreo = new NMonitoreoTurno();
            var turnoAbierto = objNMonitoreo.ConsultarTurnoAbierto(new Personal { Id = new IDPersonal { Pk_personal = (int)rolMonitoreo.FK_PERSONAL_MONITOREO } });

            criterios.Add(new CriterioValor
            {
                Criterio = new Criterio { Alias = "tcr", Campo = "FK_PERSONAL_MONITOREO" },
                Operador = OperadoresLogicos.IGUAL,
                Valor = rolMonitoreo.FK_PERSONAL_MONITOREO.ToString(),
                OperadorCriterio = OperadoresBoleanos.AND
            });
            criterios.Add(new CriterioValor
            {
                Criterio = new Criterio { Alias = "tcr", Campo = "FECHA" },
                Operador = OperadoresLogicos.IGUAL,
                Valor = rolMonitoreo.FECHA.ToString("yyyy-MM-dd"),
                OperadorCriterio = OperadoresBoleanos.AND
            });

            // Se consulta el turno que tiene registrado el monitorista
            var rol = objNRolMonitoreoTurno.ConsultarRolPersonalMonitoreo(criterios, usuario.Id.Login);

            if (rol == null)
                return string.Empty;

            var turno = rol["TURNO"].ToString();

            if (turnoAbierto != null)
            {
                var (turnoUsuario, fechaInicio, fechaFin) = ObtenerTurnoHorario(turnoAbierto);

                if (StringEnum.GetStringValue(turnoUsuario) == turno)
                    return $"E|No se puede modificar el turno del monitorista {rol[2].ToString()} debido a que ya abrió su turno del día " +
                        $"{rolMonitoreo.FECHA.ToString("dd/MM/yyyy")} en el horario de {fechaInicio.ToShortTimeString()} a {fechaFin.ToShortTimeString()}";
            }

            return string.Empty;
        }

